style.css:
/* BLACK TIDE — Spotify */

:root {
  /* swap these values to change the mood */
  --my-black: #08090a;
  --my-deep: #101113;
  --my-grey: #202124;
  --my-silver: #b8b8b8;
  --my-white: #f2f2f2;
  --my-muted: #858585;
  color-scheme: dark;
}

/* dark ocean foundation */
html,
body {
  background: var(--my-black) !important;
  color: var(--my-white) !important;
}

/* darken the main Spotify surfaces */
main,
nav,
aside,
[role="main"],
[role="navigation"] {
  background-color: var(--my-deep) !important;
  color: var(--my-white) !important;
}

/* monochrome typography */
body {
  font-family: "Helvetica Neue", Arial, sans-serif !important;
}

h1, h2, h3, h4 {
  color: var(--my-white) !important;
  letter-spacing: -0.7px !important;
}

p, span {
  text-rendering: optimizeLegibility;
}

/* silver links */
a {
  color: var(--my-silver) !important;
}

a:hover {
  color: #ffffff !important;
}

/* stormy album artwork */
img {
  filter: grayscale(100%) contrast(1.08) !important;
  transition: filter 0.3s ease, transform 0.3s ease !important;
}

img:hover {
  filter: grayscale(35%) contrast(1.12) !important;
}

/* understated controls */
button {
  border-radius: 8px !important;
}

button:hover {
  filter: brightness(1.2) !important;
}

/* subtle dark scrollbars */
* {
  scrollbar-color: #454545 #090909;
}
